// ================== FORMATEAR MENSAJE (USD y EUR a PEN) ==================
// Recibe la respuesta de CUALQUIERA de las 4 APIs (la que haya respondido)
// o el error de la última API si todas fallaron.

const ZONA = 'America/Lima';
const filas = $input.all().map(i => i.json);
const store = $getWorkflowStaticData('global'); // guarda el dato anterior para calcular variación

// ---------- URLs limpias para Google (sin parámetros de rastreo innecesarios) ----------
const linkDolar = 'https://www.google.com/search?q=dolar+hoy+en+peru';
const linkEuro = 'https://www.google.com/search?q=euro+hoy+en+peru';

// ---------- utilidades ----------
const num = v => { const n = Number(v); return Number.isFinite(n) && n > 0 ? n : null; };
const f4 = n => n.toFixed(4);
const dinero = n => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmtCorta = iso => String(iso).split('-').reverse().join('/');
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const ahora = new Date();
const hoyISO = ahora.toLocaleDateString('en-CA', { timeZone: ZONA });
const hora = Number(ahora.toLocaleString('en-US', { timeZone: ZONA, hour: 'numeric', hourCycle: 'h23' }));
const saludo = hora < 12 ? '☀️ ¡Buenos días!' : hora < 19 ? '🌤️ ¡Buenas tardes!' : '🌙 ¡Buenas noches!';

// ---------- 1. Detectar qué API respondió y normalizar ----------
function leerRespuesta() {
  const pen = filas.find(f => f.quote === 'PEN');
  const eur = filas.find(f => f.quote === 'EUR');
  if (pen && eur && num(pen.rate) && num(eur.rate)) {
    return { fuente: 'Frankfurter', usdPen: num(pen.rate), usdEur: num(eur.rate), fecha: pen.date };
  }
  const j = filas[0] || {};
  if (j.usd && num(j.usd.pen) && num(j.usd.eur)) {
    return { fuente: 'Currency API', usdPen: num(j.usd.pen), usdEur: num(j.usd.eur), fecha: j.date };
  }
  if (j.result === 'success' && j.rates && num(j.rates.PEN) && num(j.rates.EUR)) {
    const fecha = new Date(j.time_last_update_unix * 1000).toISOString().slice(0, 10);
    return { fuente: 'ExchangeRate-API', usdPen: num(j.rates.PEN), usdEur: num(j.rates.EUR), fecha };
  }
  return null;
}

const datos = leerRespuesta();

// ---------- 2. Si ninguna API respondió: mensaje de alerta ----------
if (!datos) {
  const ult = store.ultimo;
  const detalle = esc(String((filas[0] && filas[0].error && filas[0].error.message) || 'sin detalle').slice(0, 200));
  const ultTxt = ult
    ? `Último dato guardado: 1 USD = S/ ${f4(ult.usdPen)} y 1 EUR = S/ ${f4(ult.eurPen)} (${fmtCorta(ult.fecha)}).`
    : 'Aún no hay ningún dato guardado.';

  const tg = [
    '🚨 <b>No pude obtener el tipo de cambio hoy</b>',
    '',
    'Probé las 4 fuentes (Frankfurter, Currency API, ExchangeRate-API y su espejo) y ninguna respondió bien. 😕',
    '',
    `📦 ${ultTxt}`,
    `🔧 Detalle: <i>${detalle}</i>`,
    '',
    '👉 Revisa las ejecuciones del workflow en n8n.'
  ].join('\n');

  const mail = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:520px;margin:auto;background:#fff3f3;padding:20px;border-radius:16px;color:#222">
<h2 style="margin:0 0 8px 0">🚨 No pude obtener el tipo de cambio hoy</h2>
<p>Probé las 4 fuentes y ninguna respondió bien. 😕</p>
<p>📦 ${ultTxt}</p>
<p style="color:#777;font-size:13px">🔧 Detalle: ${detalle}</p>
<p>👉 Revisa las ejecuciones del workflow en n8n.</p>
</div>`;

  return [{ json: { ok: false, asunto: '🚨 Error: no se pudo obtener el tipo de cambio', mensaje_telegram: tg, mensaje_email: mail } }];
}

