const eurPen = datos.usdPen / datos.usdEur;
const penUsd = 1 / usdPen;
const penEur = 1 / eurPen;

const actual = { fecha: datos.fecha, usdPen, eurPen };
if (!store.ultimo || store.ultimo.fecha !== actual.fecha) {
  if (store.ultimo) store.anterior = store.ultimo;
  store.ultimo = actual;
}
const previo = store.anterior || null;

