  if (!previo) return '🆕 Primer registro: desde el próximo día verás cómo varía';
  const dif = valorActual - valorPrevio;
  if (Math.abs(dif) < 0.00005) return `➖ Sin cambios vs el ${fmtCorta(previo.fecha)}`;
  const pct = Math.abs((dif / valorPrevio) * 100).toFixed(2);
  return dif > 0
    ? `📈 ${etiqueta} subió S/ ${Math.abs(dif).toFixed(4)} (+${pct}%) vs el ${fmtCorta(previo.fecha)}`
    : `📉 ${etiqueta} bajó S/ ${Math.abs(dif).toFixed(4)} (−${pct}%) vs el ${fmtCorta(previo.fecha)}`;
}
const varUsd = variacion('El dólar', usdPen, previo && previo.usdPen);
const varEur = variacion('El euro', eurPen, previo && previo.eurPen);

