  .toLocaleDateString('es-PE', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });
fechaLarga = fechaLarga.charAt(0).toUpperCase() + fechaLarga.slice(1);

const desactualizado = datos.fecha < hoyISO;
const avisoFecha = desactualizado
  ? `📌 Último dato publicado (${fmtCorta(datos.fecha)}): hoy aún no hay actualización (fin de semana, feriado o la fuente no ha publicado).`
  : '';
