const avisoRespaldo = respaldo ? '🔁 Se usó una fuente de respaldo porque la principal no respondió.' : '';

const explicacion = 'El tipo de cambio dice cuántos soles cuesta 1 dólar o 1 euro. Si el número sube, necesitas más soles para comprar la misma cantidad de moneda extranjera; si baja, necesitas menos.';
const disclaimer = 'Es un tipo de cambio de referencia (promedio de mercado), no el precio de compra/venta de tu banco o casa de cambio. Ellos aplican su propio margen: confirma antes de operar.';

